    @wrap_result
    def get_parameters_for_all(self, class_name, timeout=10):
        """Get parameters for all items.

        :param string class_name: E.g. BTS, SMOD, BBU, RMOD, ALD, LNCEL, GNCEL or WNCEL
        :param float timeout: Time to wait for positive procedure result.


        :rtype: list
        :return: List of items parameters dicts.

        :note: For cells new keyword was introduced get_cell_list - vallid from xL18/SBTS18
        """
        timeout = time_to_seconds(timeout)
        str(class_name)

        return self._api_client.execute_infomodel_request("getParametersForAllEntities", {"entityType": class_name}, timeout)

    def get_ids_for_all(self, class_name, timeout=10):
        """Get IDs for all items of given class.

        :param string class_name: E.g. BTS, SMOD, BBU, RMOD, ALD, LNCEL, GNCEL or WNCEL
        :param float timeout: Time to wait for positive procedure result.


        :rtype: list
        :return: List of distnames to the connected entity id
        """
        timeout = time_to_seconds(timeout)
        str(class_name)

        items = self._api_client.execute_infomodel_request(
            "getParametersForAllEntities", {"entityType": class_name}, timeout)
        result = [item["id"] for item in items]

        if class_name == "LNCEL":
            iot_cells = [item["nbIoTCell"]
                         for item in items if item.get("nbIoTCell")]
            iot_cells_dn = [elem['distName'] for elem in iot_cells]
            result = iot_cells_dn + result
        return result

