    def get_ald_id_by_module_connector(self, module_id, connector_label=None, timeout=10):
        """Get ALD id by module connector.

        :param string module_id: Module ID
        :param string connector_label: Connector label
        :param float timeout: Time to wait for positive procedure result.


        :rtype: string
        :return: ALD ID
        """
        timeout = time_to_seconds(timeout)
        str(module_id)

        parameters = {"id": module_id}
        if connector_label:
            parameters["connectorLabel"] = connector_label

        result = self._api_client.execute_infomodel_request(
            "getAldIdByModuleConnector", parameters, timeout)

        if not result:
            raise AdminApiProcedureFailureException(
                "No ALD found on {} {}".format(module_id, connector_label))
        if isinstance(result, list) and len(result) == 1:
            return result[0]
        return result

    def get_active_alarms(self, severity=None, timeout=10):
        """Get active alarms.

        :param string severity: Alarm severity (critical, major, minor or warning)
        :param float timeout: Time to wait for positive procedure result.


        :rtype: list
        :return: list of alarm objects
        """
        timeout = time_to_seconds(timeout)
        assert severity in ("critical", "major", "minor", "warning", None)

        return self._get_alarms("currentAlarms", severity, False, timeout)

    def get_alarms(self, timeout=10):
        """Get alarms.

        :param float timeout: Time to wait for positive procedure result.


        :rtype: list
        :return: list alarms with additional info
        """
        timeout = time_to_seconds(timeout)
        return self._api_client.execute_infomodel_request("getActiveAlarms", None, timeout)

    def start_historical_alarm_tracker(self, timeout=10):
        """Start historical alarm tracker.

        :param float timeout: Time to wait for positive procedure result.

        """
        timeout = time_to_seconds(timeout)
        self._api_client.execute_infomodel_request(
            "abnormalities", {"type": "startHistoricalTracker"}, timeout)

    def get_historical_alarms(self, severity=None, load_history=False, timeout=10):
        """Get historical alarms.

        :param string severity: Alarm severity (critical, major, minor or warning)
        :param boolean load_history: load entire BTS history (may significantly extent time for request)
        :param float timeout: Time to wait for positive procedure result.


        :rtype: list
        :return: list of alarm objects
        """
        load_history = to_boolean(load_history)
        timeout = time_to_seconds(timeout)
        assert severity in ("critical", "major", "minor", "warning", None)

        return self._get_alarms("historicalAlarms", severity, load_history, timeout)

    @wrap_result
    def _get_alarms(self, alarm_type, severity, load_history, timeout):

        parameters = {"type": alarm_type}
        if load_history:
            parameters["loadHistory"] = load_history
        if severity:
            parameters["severity"] = severity
        return self._api_client.execute_infomodel_request("abnormalities", parameters, timeout)

    def assert_alarm_active(self, parameters=None, timeout=60):
        """Assert that there is any active alarm matching given parameters.

        :param string parameters: Requierd alarm parameters. (See `parameters` syntax in `Assert` keyword reference)
        :param float timeout: Time to wait for alarm activation.


        **EXAMPLE:**

        ::

            Assert alarm active    faultId=49, severity=Critical
        """
        timeout = time_to_seconds(timeout)
        assert isinstance(parameters, six.string_types) or parameters is None

        return self._api_client.execute_infomodel_subscription("subscribeForActiveAlarms", {}, AnyObjectValidator(parameters), timeout)

    def assert_alarm_inactive(self, parameters=None, timeout=60):
        """Assert that there's no active alarm matching given parameters.

        :param string parameters: Requierd alarm parameters. (See `parameters` syntax in `Assert` keyword reference)
        :param float timeout: Time to wait for alarm deactivation.

        """
        timeout = time_to_seconds(timeout)
        assert isinstance(parameters, six.string_types) or parameters is None

        return self._api_client.execute_infomodel_subscription("subscribeForActiveAlarms", {}, NoneObjectsValidator(parameters), timeout)

    @classmethod
    def add_allowed_alarm(self, parameters):
        """Add allowed alarm.

        :param string parameters: Allowed alarm parameters. (See `parameters` syntax in `Assert` keyword reference)

        """
        self.allowed_alarm_validators.append(ObjectValidator(parameters))

    @classmethod
    def clear_allowed_alarms_list(self):
        """Clear allowed alarms list.


        """
        self.allowed_alarm_validators = []

    def assert_no_unexpected_active_alarms(self):
        """Assert no unexpected active alarms.


        """
        self._assert_no_unexpected_alarms(self.get_active_alarms())

    def assert_no_unexpected_historical_alarms(self, load_history=False):
        """Assert no unexpected historical alarms.

        :param boolean load_history: load entire BTS history (may significantly extent time for request)

        """
        load_history = to_boolean(load_history)
        self._assert_no_unexpected_alarms(
            self.get_historical_alarms(load_history=load_history))

    def _assert_no_unexpected_alarms(self, alarms):
        unexpected_alarms = list(filter(lambda a: not any(validator.check(
            a) for validator in self.allowed_alarm_validators), alarms))
        if unexpected_alarms:
            raise AdminApiProcedureFailureException(
                "Unexpected alarms:\n{}".format(unexpected_alarms))

    def assert_(self, class_name, id, parameters=None, timeout=10):
        """Assert that item exists and matches given parameters.

        :param string class_name: E.g. BTS, SMOD, BBU, RMOD, ALD, LNCEL, GNCEL or WNCEL
        :param string id: item ID
        :param string parameters: Requierd item parameters. None means no parameter value validation.
        :param float timeout: Time to wait for matching item.


        |

        **PARAMETERS syntax:**
            - PARAMETER1 OPERATOR1 VALUE1, PARAMETER2 OPERATOR2 VALUE2, ...
                * example: status=disabled, temperature>100, temperature<=120
                * single spaces between elements are allowed with one exception - see empty VALUE
            - PARAMETERs:
                * simple: temperature, status, etc.
                * nested: stateInfo.availabilityStatus, etc.
                * lists: alarms[5], stateInfo.reasoningStatus[?], alarms[*]
                    * \* means all elements
                    * ? means any element
            - OPERATORs: >, <, >=, <=, =, !=
            - VALUEs:
                * literal: 5, disabled
                * regex:
                    * positive match: parameter=regex"[Oo]nline"
                    * negative match: parameter!=regex"validated|onAirDone"
                * empty: string 'empty' is interpreted as an empty value, but there may be no space before it
                    * correct: parameter=empty, parameter !=empty
                    * incorrect: parameter = empty

        |

        **EXAMPLE:**

        ::

            Assert    RMOD    ${RMOD_ID}    productName=FXEA, ipAddress=192.168.253.204

        """
        timeout = time_to_seconds(timeout)

        str(class_name)
        str(id)

        return self._api_client.execute_infomodel_subscription(
            "subscribeForParameters", {"className": class_name, "id": id}, ObjectValidator(parameters), timeout)

    def assert_any(self, class_name, parameters=None, timeout=10):
        """Assert that any item of given class exists and matches given parameters.

        :param string class_name: E.g. BTS, SMOD, BBU, RMOD, ALD, LNCEL, GNCEL or WNCEL
        :param string parameters: Requierd item parameters. (See `parameters` syntax in `Assert` keyword reference)
        :param float timeout: Time to wait for matching item.

        """
        timeout = time_to_seconds(timeout)

        str(class_name)
        assert isinstance(parameters, six.string_types) or parameters is None

        return self._api_client.execute_infomodel_subscription(
            "subscribeForAllParameters", {"className": class_name}, AnyObjectValidator(parameters), timeout)

